#### 3. Policy Information Point (PIP) Integration

**Attribute Retrieval Strategy:**

```csharp
// AttributeService.cs - Coordinates attribute retrieval from multiple PIPs
public class AttributeService : IAttributeService
{
    private readonly IUserAttributeProvider _userProvider;
    private readonly IResourceAttributeProvider _resourceProvider;
    private readonly IContextProvider _contextProvider;
    private readonly IDistributedCache _cache;

    public async Task<SubjectAttributes> GetSubjectAttributesAsync(
        string userId,
        CancellationToken cancellationToken)
    {
        var cacheKey = $"subject_attrs:{userId}";

        // Check cache first
        var cached = await _cache.GetStringAsync(cacheKey, cancellationToken);
        if (cached != null)
        {
            return JsonSerializer.Deserialize<SubjectAttributes>(cached);
        }

        // Fetch from authoritative sources
        var attributes = new SubjectAttributes
        {
            UserId = userId,
            Role = await _userProvider.GetRoleAsync(userId),
            AssignedStates = await _userProvider.GetAssignedStatesAsync(userId),
            Department = await _userProvider.GetDepartmentAsync(userId),
            ClearanceLevel = await _userProvider.GetClearanceLevelAsync(userId)
        };

        // Cache for 5 minutes (user attributes relatively stable)
        await _cache.SetStringAsync(
            cacheKey,
            JsonSerializer.Serialize(attributes),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) },
            cancellationToken);

        return attributes;
    }

    public async Task<ResourceAttributes> GetResourceAttributesAsync(
        string resourceType,
        string resourceId,
        CancellationToken cancellationToken)
    {
        // Resource attributes may change frequently, use shorter cache
        var cacheKey = $"resource_attrs:{resourceType}:{resourceId}";

        var cached = await _cache.GetStringAsync(cacheKey, cancellationToken);
        if (cached != null)
        {
            return JsonSerializer.Deserialize<ResourceAttributes>(cached);
        }

        var attributes = await _resourceProvider.GetAttributesAsync(resourceType, resourceId);

        // Cache for 1 minute (resource metadata may change)
        await _cache.SetStringAsync(
            cacheKey,
            JsonSerializer.Serialize(attributes),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1) },
            cancellationToken);

        return attributes;
    }

    public ContextAttributes GetContextAttributes(HttpContext httpContext)
    {
        // Context attributes derived from current request
        return new ContextAttributes
        {
            Time = new TimeContext
            {
                Timestamp = DateTime.UtcNow,
                Hour = DateTime.UtcNow.Hour,
                DayOfWeek = DateTime.UtcNow.DayOfWeek.ToString()
            },
            Location = new LocationContext
            {
                IPAddress = httpContext.Connection.RemoteIpAddress?.ToString(),
                Country = httpContext.Request.Headers["CloudFront-Viewer-Country"].FirstOrDefault() ?? "Unknown"
            },
            Device = new DeviceContext
            {
                UserAgent = httpContext.Request.Headers["User-Agent"].FirstOrDefault(),
                Type = DetermineDeviceType(httpContext.Request.Headers["User-Agent"])
            },
            PurposeOfUse = httpContext.Request.Headers["X-Purpose-Of-Use"].FirstOrDefault() ?? "Unspecified"
        };
    }
}
```

