#### 4. Policy Enforcement Point (PEP) Implementation

**Middleware-Based PEP (ASP.NET Core):**

```csharp
// AbacAuthorizationMiddleware.cs
public class AbacAuthorizationMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IPolicyDecisionPoint _pdp;
    private readonly IAttributeService _attributeService;
    private readonly ILogger<AbacAuthorizationMiddleware> _logger;

    public AbacAuthorizationMiddleware(
        RequestDelegate next,
        IPolicyDecisionPoint pdp,
        IAttributeService attributeService,
        ILogger<AbacAuthorizationMiddleware> logger)
    {
        _next = next;
        _pdp = pdp;
        _attributeService = attributeService;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Skip authorization for public endpoints
        var endpoint = context.GetEndpoint();
        if (endpoint?.Metadata?.GetMetadata<AllowAnonymousAttribute>() != null)
        {
            await _next(context);
            return;
        }

        // Extract resource information from route
        var resourceType = context.Request.RouteValues["controller"]?.ToString();
        var resourceId = context.Request.RouteValues["id"]?.ToString();
        var action = DetermineAction(context.Request.Method);

        // Build authorization request
        var authzRequest = new AuthorizationRequest
        {
            Subject = await _attributeService.GetSubjectAttributesAsync(context.User.Identity.Name),
            Resource = resourceId != null
                ? await _attributeService.GetResourceAttributesAsync(resourceType, resourceId)
                : new ResourceAttributes { Type = resourceType },
            Action = action,
            Context = _attributeService.GetContextAttributes(context)
        };

        // Call PDP for decision
        var stopwatch = Stopwatch.StartNew();
        var decision = await _pdp.EvaluateAsync(authzRequest, context.RequestAborted);
        stopwatch.Stop();

        _logger.LogInformation(
            "Authorization decision for {User} accessing {Resource}: {Decision} ({ElapsedMs}ms)",
            context.User.Identity.Name,
            resourceId ?? resourceType,
            decision.Decision,
            stopwatch.ElapsedMilliseconds);

        // Enforce decision
        if (decision.Decision != AuthorizationDecision.Permit)
        {
            _logger.LogWarning(
                "Access denied for {User} to {Resource}: {Reason}",
                context.User.Identity.Name,
                resourceId ?? resourceType,
                decision.Status.Message);

            context.Response.StatusCode = 403;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "Forbidden",
                message = decision.Status.Message
            });
            return;
        }

        // Execute obligations
        await ExecuteObligationsAsync(context, decision.Obligations);

        // Store decision context for downstream use
        context.Items["AuthorizationDecision"] = decision;

        await _next(context);
    }

    private async Task ExecuteObligationsAsync(
        HttpContext context,
        List<Obligation> obligations)
    {
        foreach (var obligation in obligations)
        {
            switch (obligation.Type)
            {
                case "log":
                    await ExecuteAuditObligationAsync(context, obligation);
                    break;
                case "transform":
                    // Store transformation rules for response filtering
                    context.Items["DataTransformations"] = obligation.Parameters;
                    break;
                default:
                    _logger.LogWarning("Unknown obligation type: {Type}", obligation.Type);
                    break;
            }
        }
    }

    private async Task ExecuteAuditObligationAsync(HttpContext context, Obligation obligation)
    {
        var auditEvent = new AuditEvent
        {
            Timestamp = DateTime.UtcNow,
            EventType = obligation.Parameters["event"]?.ToString(),
            Subject = obligation.Parameters["subject"]?.ToString(),
            Resource = obligation.Parameters["resource"]?.ToString(),
            Purpose = obligation.Parameters["purpose"]?.ToString(),
            IPAddress = context.Connection.RemoteIpAddress?.ToString(),
            UserAgent = context.Request.Headers["User-Agent"].FirstOrDefault()
        };

        // Async audit logging (don't block request)
        _ = Task.Run(async () =>
        {
            try
            {
                await _auditService.LogEventAsync(auditEvent);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to log audit event");
            }
        });
    }

    private string DetermineAction(string httpMethod)
    {
        return httpMethod.ToUpper() switch
        {
            "GET" => "read",
            "POST" => "create",
            "PUT" => "update",
            "PATCH" => "update",
            "DELETE" => "delete",
            _ => "unknown"
        };
    }
}
```

