#### 5. Policy Decision Point (PDP) - Open Policy Agent Integration

**OPA Policy Example (Rego Language):**

```rego
# Provider claims access policy
package gainwell.claims.provider_access

import future.keywords.if
import future.keywords.in

default allow = false

# Provider can read claims for their patients
allow if {
    input.subject.role == "Provider"
    input.action == "read"
    input.resource.type == "Claim"

    # Provider NPI matches claim provider
    input.subject.npi == input.resource.providerNPI

    # Provider assigned to claim state
    input.resource.state in input.subject.assignedStates

    # Business hours check
    business_hours

    # Active network status
    input.subject.networkStatus == "Active"
}

# Business hours: 6 AM to 10 PM
business_hours if {
    input.context.time.hour >= 6
    input.context.time.hour < 22
}

# Obligations to execute when access is granted
obligations[obligation] {
    allow
    obligation := {
        "id": "audit-log",
        "type": "log",
        "parameters": {
            "event": "PROVIDER_CLAIM_ACCESS",
            "subject": input.subject.userId,
            "resource": input.resource.id,
            "purpose": input.context.purposeOfUse,
            "timestamp": time.now_ns()
        }
    }
}

obligations[obligation] {
    allow
    input.subject.clearanceLevel < 5
    obligation := {
        "id": "redact-sensitive",
        "type": "transform",
        "parameters": {
            "fields": ["memberSSN", "memberAddress", "memberPhone"]
        }
    }
}

# Deny with reason if conditions not met
deny[reason] {
    input.subject.role == "Provider"
    input.action == "read"
    input.resource.type == "Claim"
    not input.subject.npi == input.resource.providerNPI
    reason := "Provider NPI does not match claim provider"
}

deny[reason] {
    input.subject.role == "Provider"
    input.action == "read"
    input.resource.type == "Claim"
    not input.resource.state in input.subject.assignedStates
    reason := "Provider not assigned to claim state"
}

deny[reason] {
    not business_hours
    reason := "Access denied outside business hours (6 AM - 10 PM)"
}
```

**OPA Integration Client (C#):**

```csharp
// OpaPolicyDecisionPoint.cs
public class OpaPolicyDecisionPoint : IPolicyDecisionPoint
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ILogger<OpaPolicyDecisionPoint> _logger;
    private readonly string _opaUrl;

    public OpaPolicyDecisionPoint(
        HttpClient httpClient,
        IDistributedCache cache,
        IConfiguration configuration,
        ILogger<OpaPolicyDecisionPoint> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
        _opaUrl = configuration["OPA:Url"] ?? "http://opa-service:8181";
    }

    public async Task<AuthorizationDecision> EvaluateAsync(
        AuthorizationRequest request,
        CancellationToken cancellationToken = default)
    {
        // Generate cache key from request attributes
        var cacheKey = GenerateCacheKey(request);

        // Check cache for identical request
        var cachedDecision = await _cache.GetStringAsync(cacheKey, cancellationToken);
        if (cachedDecision != null)
        {
            _logger.LogDebug("Cache hit for authorization request");
            return JsonSerializer.Deserialize<AuthorizationDecision>(cachedDecision);
        }

        // Call OPA REST API
        var opaRequest = new
        {
            input = new
            {
                subject = request.Subject,
                resource = request.Resource,
                action = request.Action,
                context = request.Context
            }
        };

        var response = await _httpClient.PostAsJsonAsync(
            $"{_opaUrl}/v1/data/gainwell/claims/provider_access",
            opaRequest,
            cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError("OPA evaluation failed with status {StatusCode}", response.StatusCode);
            return new AuthorizationDecision
            {
                Decision = AuthorizationDecision.Indeterminate,
                Status = new DecisionStatus
                {
                    Code = "PDP_ERROR",
                    Message = "Policy evaluation failed"
                }
            };
        }

        var opaResponse = await response.Content.ReadFromJsonAsync<OpaResponse>(cancellationToken);

        var decision = new AuthorizationDecision
        {
            Decision = opaResponse.Result.Allow ? AuthorizationDecision.Permit : AuthorizationDecision.Deny,
            Status = new DecisionStatus
            {
                Code = "OK",
                Message = opaResponse.Result.Allow
                    ? "Access granted"
                    : string.Join(", ", opaResponse.Result.Deny)
            },
            Obligations = opaResponse.Result.Obligations ?? new List<Obligation>(),
            EvaluationDetails = new EvaluationDetails
            {
                EvaluationTimeMs = opaResponse.DecisionId != null ? 0 : 0, // OPA doesn't provide this
                CacheHit = false
            }
        };

        // Cache decision for 1 minute (shorter for dynamic policies)
        await _cache.SetStringAsync(
            cacheKey,
            JsonSerializer.Serialize(decision),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1) },
            cancellationToken);

        return decision;
    }

    private string GenerateCacheKey(AuthorizationRequest request)
    {
        // Create deterministic cache key from request attributes
        var keyComponents = new[]
        {
            request.Subject.UserId,
            request.Subject.Role,
            request.Resource.Type,
            request.Resource.Id,
            request.Action,
            request.Context.Time.Hour.ToString()
        };

        var keyString = string.Join(":", keyComponents);
        return $"authz:{ComputeHash(keyString)}";
    }

    private string ComputeHash(string input)
    {
        using var sha256 = SHA256.Create();
        var bytes = Encoding.UTF8.GetBytes(input);
        var hash = sha256.ComputeHash(bytes);
        return Convert.ToBase64String(hash);
    }
}

public class OpaResponse
{
    [JsonPropertyName("decision_id")]
    public string DecisionId { get; set; }

    [JsonPropertyName("result")]
    public OpaResult Result { get; set; }
}

public class OpaResult
{
    [JsonPropertyName("allow")]
    public bool Allow { get; set; }

    [JsonPropertyName("deny")]
    public List<string> Deny { get; set; }

    [JsonPropertyName("obligations")]
    public List<Obligation> Obligations { get; set; }
}
```

