public class AbacAuthorizationFilter : IAsyncAuthorizationFilter
{
    private readonly IPolicyDecisionPoint _pdp;
    private readonly IAttributeService _attributeService;

    public async Task OnAuthorizationAsync(AuthorizationFilterContext context)
    {
        // Build authorization request
        var request = await BuildAuthorizationRequestAsync(context);

        // Get decision from PDP
        var decision = await _pdp.EvaluateAsync(request);

        // Enforce decision
        if (decision.Decision != AuthorizationDecision.Permit)
